-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000019_finalization.sql
-- =============================================================================
-- 0019 FINALIZATION
--   * Promotion codes are redeemable at checkout. The discount is computed
--     ONLY here (private.apply_promotion), inside create_order, from database
--     prices. Optional usage limit and once-per-customer.
--   * Codes are no longer readable by the public API unless the promotion is
--     shown on the homepage (private codes cannot be enumerated).
--   * admin_analytics(): sales over time, by category, best sellers, status
--     distribution, payments, inventory, promotions, printing.
--   * storage_orphans(): customer uploads that were never attached (sweep).
-- =============================================================================

alter table public.promotions
  add column max_redemptions   integer check (max_redemptions > 0),
  add column once_per_customer boolean not null default true;

drop policy promotions_public_read on public.promotions;
create policy promotions_public_read on public.promotions for select to anon, authenticated
  using (is_active and show_on_homepage
         and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()));

-- p_lines: create_order lines [{item_type, product_id, unit, qty}, ...]
-- Eligible amount = product lines matching the promotion's product / category
-- (incl. subcategories); printing jobs are never discounted.
create or replace function private.apply_promotion(
  p_code text, p_lines jsonb, p_subtotal numeric, p_fee numeric, p_user uuid, p_lock boolean)
returns table (promotion_id uuid, discount_etb numeric, title_en text, title_am text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v        public.promotions;
  v_code   text := lower(btrim(coalesce(p_code, '')));
  v_amount numeric(12,2);
  v_disc   numeric(12,2);
begin
  if v_code !~ '^[a-z0-9_-]{3,30}$' then perform private.app_error('invalid_promo_code'); end if;
  if p_lock then
    select * into v from public.promotions p where lower(p.code::text) = v_code for update;
  else
    select * into v from public.promotions p where lower(p.code::text) = v_code;
  end if;
  if not found or not v.is_active
     or (v.starts_at is not null and v.starts_at > now())
     or (v.ends_at is not null and v.ends_at <= now()) then
    perform private.app_error('invalid_promo_code');
  end if;
  if p_subtotal < v.min_order_etb then
    perform private.app_error('promo_min_order', v.min_order_etb::text);
  end if;

  select coalesce(sum((l ->> 'unit')::numeric * (l ->> 'qty')::integer), 0) into v_amount
    from jsonb_array_elements(p_lines) l
    left join public.products pr on pr.id = (l ->> 'product_id')::uuid
    left join public.categories c on c.id = pr.category_id
   where l ->> 'item_type' = 'product'
     and (v.product_id is null or pr.id = v.product_id)
     and (v.category_id is null or pr.category_id = v.category_id or c.parent_id = v.category_id);
  if v_amount <= 0 then perform private.app_error('promo_not_applicable'); end if;

  if v.max_redemptions is not null and (
       select count(*) from public.orders o
        where o.promotion_id = v.id and o.status not in ('expired', 'cancelled')) >= v.max_redemptions then
    perform private.app_error('promo_limit_reached');
  end if;
  if v.once_per_customer and p_user is not null and exists (
       select 1 from public.orders o
        where o.promotion_id = v.id and o.user_id = p_user and o.status not in ('expired', 'cancelled')) then
    perform private.app_error('promo_already_used');
  end if;

  v_disc := case when v.discount_type = 'percent' then round(v_amount * v.discount_value / 100, 2)
                 else least(v.discount_value, v_amount) end;
  v_disc := least(v_disc, p_subtotal + p_fee - 1); -- an order always costs at least 1 ETB
  if v_disc <= 0 then perform private.app_error('promo_not_applicable'); end if;
  return query select v.id, v_disc, v.title_en, v.title_am;
end;
$$;

-- Checkout preview (server only, rate limited by the app). Same rules as
-- create_order; delivery fee excluded (shown separately).
create or replace function public.quote_promotion(p_code text, p_items jsonb, p_user_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_lines    jsonb := '[]'::jsonb;
  v_subtotal numeric(12,2) := 0;
  r          record;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 60 then
    perform private.app_error('invalid_cart');
  end if;
  for r in
    select p.id, coalesce(p.sale_price_etb, p.price_etb) as unit, sum((e ->> 'quantity')::integer)::integer as qty
      from jsonb_array_elements(p_items) e
      join public.products p on p.id = (e ->> 'product_id')::uuid and p.status = 'active'
     where e ->> 'type' = 'product' and coalesce(e ->> 'quantity', '') ~ '^[0-9]{1,3}$'
       and coalesce(e ->> 'product_id', '') ~ '^[0-9a-f-]{36}$'
     group by p.id
  loop
    v_subtotal := v_subtotal + r.unit * r.qty;
    v_lines := v_lines || jsonb_build_object('item_type', 'product', 'product_id', r.id, 'unit', r.unit, 'qty', r.qty);
  end loop;
  v_subtotal := v_subtotal + coalesce((
    select sum(j.total_etb) from public.printing_jobs j
     where j.user_id = p_user_id and j.status = 'awaiting_payment' and j.order_id is null
       and j.id in (select (e ->> 'printing_job_id')::uuid from jsonb_array_elements(p_items) e
                     where e ->> 'type' = 'printing' and coalesce(e ->> 'printing_job_id', '') ~ '^[0-9a-f-]{36}$')), 0);
  return (select to_jsonb(q) from private.apply_promotion(p_code, v_lines, v_subtotal, 0, p_user_id, false) q);
end;
$$;

create or replace function public.create_order(p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key         uuid := (p_input ->> 'idempotency_key')::uuid;
  v_phone       text := p_input #>> '{customer,phone}';
  v_name        text := btrim(coalesce(p_input #>> '{customer,full_name}', ''));
  v_method      public.fulfillment_method := (p_input #>> '{fulfillment,method}')::public.fulfillment_method;
  v_address     text := nullif(btrim(coalesce(p_input #>> '{fulfillment,address_line}', '')), '');
  v_instr       text := nullif(btrim(coalesce(p_input #>> '{fulfillment,instructions}', '')), '');
  v_items       jsonb := p_input -> 'items';
  v_delivery    jsonb := private.setting('delivery');
  v_existing    public.orders;
  v_zone        public.delivery_zones;
  v_bank        public.bank_accounts;
  v_product     public.products;
  v_job         public.printing_jobs;
  v_customer_id uuid;
  v_order_id    uuid;
  v_order_no    text;
  v_subtotal    numeric(12,2) := 0;
  v_fee         numeric(12,2) := 0;
  v_unit        numeric(12,2);
  v_after       integer;
  v_threshold   numeric;
  r             record;
  v_lines       jsonb := '[]'::jsonb;
  v_promo_code  text := nullif(btrim(coalesce(p_input ->> 'promotion_code', '')), '');
  v_promo       record;
  v_promo_id    uuid;
  v_discount    numeric(12,2) := 0;
begin
  if v_key is null then perform private.app_error('invalid_request', 'idempotency_key'); end if;

  -- Serialize concurrent retries of the same checkout.
  perform pg_advisory_xact_lock(hashtext(v_key::text));

  select * into v_existing from public.orders where idempotency_key = v_key;
  if found then
    -- Possession of the (random, client-held) idempotency key proves this is
    -- the same checkout; rotate access tokens so the client gets fresh ones.
    if v_existing.customer_phone <> v_phone or v_existing.status <> 'awaiting_payment' then
      perform private.app_error('idempotency_conflict');
    end if;
    update public.orders
       set access_token_hash = p_input ->> 'access_token_hash',
           tracking_code_hash = p_input ->> 'tracking_code_hash'
     where id = v_existing.id;
    return jsonb_build_object('order_id', v_existing.id, 'order_number', v_existing.order_number,
                              'total_etb', v_existing.total_etb, 'replayed', true);
  end if;

  -- ---- Basic validation (the app validates too; this is defence in depth)
  if char_length(v_name) not between 2 and 120 then perform private.app_error('invalid_name'); end if;
  if v_phone is null or v_phone !~ '^\+251[79][0-9]{8}$' then perform private.app_error('invalid_phone'); end if;
  if v_method is null then perform private.app_error('invalid_fulfillment'); end if;
  if jsonb_typeof(v_items) <> 'array' or jsonb_array_length(v_items) not between 1 and 50 then
    perform private.app_error('invalid_cart');
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_items) e
    where coalesce(e ->> 'type', '') not in ('product', 'printing')
       or (e ->> 'type' = 'product' and (
             coalesce(e ->> 'quantity', '') !~ '^[0-9]{1,3}$'
             or (e ->> 'quantity')::integer not between 1 and 100
             or coalesce(e ->> 'product_id', '') !~ '^[0-9a-f-]{36}$'))
       or (e ->> 'type' = 'printing' and coalesce(e ->> 'printing_job_id', '') !~ '^[0-9a-f-]{36}$')
  ) then
    perform private.app_error('invalid_cart');
  end if;

  -- ---- Products: lock rows in a stable order (prevents deadlocks), verify stock
  for r in
    select (e ->> 'product_id')::uuid as product_id, sum((e ->> 'quantity')::integer)::integer as qty
    from jsonb_array_elements(v_items) e
    where e ->> 'type' = 'product'
    group by 1
    order by 1
  loop
    if r.qty > 100 then perform private.app_error('invalid_quantity', r.product_id::text); end if;
    select * into v_product from public.products where id = r.product_id for update;
    if not found or v_product.status <> 'active' then
      perform private.app_error('product_unavailable', r.product_id::text);
    end if;
    if v_product.track_inventory and v_product.stock_quantity < r.qty then
      perform private.app_error('out_of_stock', r.product_id::text);
    end if;
    v_unit := coalesce(v_product.sale_price_etb, v_product.price_etb);
    v_subtotal := v_subtotal + v_unit * r.qty;
    v_lines := v_lines || jsonb_build_object(
      'item_type', 'product', 'product_id', v_product.id, 'name_en', v_product.name_en,
      'name_am', v_product.name_am, 'sku', v_product.sku, 'unit', v_unit, 'qty', r.qty,
      'track', v_product.track_inventory);
  end loop;

  -- ---- Printing jobs: must be priced, unpaid, unattached, and owned by caller
  for r in
    select distinct (e ->> 'printing_job_id')::uuid as job_id, e ->> 'access_token_hash' as token_hash
    from jsonb_array_elements(v_items) e
    where e ->> 'type' = 'printing'
    order by 1
  loop
    select * into v_job from public.printing_jobs where id = r.job_id for update;
    if not found or v_job.access_token_hash is distinct from r.token_hash then
      perform private.app_error('printing_job_not_found', r.job_id::text);
    end if;
    if v_job.status <> 'awaiting_payment' or v_job.order_id is not null or v_job.total_etb is null then
      perform private.app_error('printing_job_not_payable', v_job.job_number);
    end if;
    v_subtotal := v_subtotal + v_job.total_etb;
    v_lines := v_lines || jsonb_build_object(
      'item_type', 'printing', 'printing_job_id', v_job.id,
      'name_en', 'Printing job ' || v_job.job_number, 'name_am', 'የህትመት ስራ ' || v_job.job_number,
      'sku', v_job.job_number, 'unit', v_job.total_etb, 'qty', 1, 'track', false);
  end loop;

  if jsonb_array_length(v_lines) = 0 then perform private.app_error('invalid_cart'); end if;

  -- ---- Fulfillment & delivery fee (server-side only)
  if v_method = 'pickup' then
    if not coalesce((v_delivery ->> 'pickup_enabled')::boolean, true) then
      perform private.app_error('pickup_unavailable');
    end if;
    v_address := null;
  else
    if not coalesce((v_delivery ->> 'delivery_enabled')::boolean, true) then
      perform private.app_error('delivery_unavailable');
    end if;
    select * into v_zone from public.delivery_zones
     where id = nullif(p_input #>> '{fulfillment,delivery_zone_id}', '')::uuid and is_active;
    if not found then perform private.app_error('invalid_delivery_zone'); end if;
    if v_address is null or char_length(v_address) not between 3 and 300 then
      perform private.app_error('invalid_address');
    end if;
    v_fee := v_zone.fee_etb;
    v_threshold := nullif(v_delivery ->> 'free_delivery_threshold_etb', '')::numeric;
    if v_threshold is not null and v_subtotal >= v_threshold then
      v_fee := 0;
    end if;
  end if;
  if v_instr is not null and char_length(v_instr) > 500 then perform private.app_error('invalid_instructions'); end if;

  -- ---- Promotion code (validated and priced here only; the browser value is never trusted)
  if v_promo_code is not null then
    select * into v_promo from private.apply_promotion(
      v_promo_code, v_lines, v_subtotal, v_fee, nullif(current_setting('app.ordering_user_id', true), '')::uuid, true);
    v_promo_id := v_promo.promotion_id;
    v_discount := v_promo.discount_etb;
  end if;

  -- ---- Bank account shown to the customer (snapshotted)
  select * into v_bank from public.bank_accounts
   where is_active
     and (p_input ->> 'bank_account_id' is null or id = (p_input ->> 'bank_account_id')::uuid)
   order by sort_order, created_at
   limit 1;
  if not found then perform private.app_error('no_bank_account'); end if;

  -- ---- Customer (guest, keyed by phone)
  insert into public.customers as c (full_name, phone, order_count, last_order_at)
  values (v_name, v_phone, 1, now())
  on conflict (phone) do update
     set full_name = excluded.full_name, order_count = c.order_count + 1, last_order_at = now()
  returning id into v_customer_id;

  if v_method = 'delivery' then
    insert into public.addresses as a (customer_id, city, address_line, instructions)
    values (v_customer_id, v_zone.name_en, v_address, v_instr)
    on conflict (customer_id, city, address_line) do update
       set last_used_at = now(), instructions = excluded.instructions;
  end if;

  -- ---- Order
  perform private.set_status_note('Order created');
  insert into public.orders (
    access_token_hash, tracking_code_hash, idempotency_key, customer_id, customer_name, customer_phone,
    fulfillment_method, delivery_zone_id, city, address_line, delivery_instructions,
    subtotal_etb, delivery_fee_etb, discount_etb, total_etb,
    promotion_id, bank_account_id, bank_snapshot, locale, payment_due_at)
  values (
    p_input ->> 'access_token_hash', p_input ->> 'tracking_code_hash', v_key, v_customer_id, v_name, v_phone,
    v_method, v_zone.id, case when v_method = 'delivery' then v_zone.name_en end, v_address, v_instr,
    v_subtotal, v_fee, v_discount, v_subtotal + v_fee - v_discount,
    v_promo_id, v_bank.id,
    jsonb_build_object('bank_name', v_bank.bank_name, 'account_holder', v_bank.account_holder,
                       'account_number', v_bank.account_number, 'branch', v_bank.branch,
                       'instructions_en', v_bank.instructions_en, 'instructions_am', v_bank.instructions_am),
    case when p_input ->> 'locale' = 'am' then 'am' else 'en' end,
    now() + make_interval(hours => coalesce((v_delivery ->> 'payment_window_hours')::integer, 24)))
  returning id, order_number into v_order_id, v_order_no;

  -- ---- Lines + stock reservation
  for r in select * from jsonb_array_elements(v_lines) l(line) loop
    insert into public.order_items (order_id, item_type, product_id, printing_job_id, name_en, name_am, sku,
                                    unit_price_etb, quantity, line_total_etb)
    values (v_order_id, (r.line ->> 'item_type')::public.order_item_type,
            (r.line ->> 'product_id')::uuid, (r.line ->> 'printing_job_id')::uuid,
            r.line ->> 'name_en', r.line ->> 'name_am', r.line ->> 'sku',
            (r.line ->> 'unit')::numeric, (r.line ->> 'qty')::integer,
            (r.line ->> 'unit')::numeric * (r.line ->> 'qty')::integer);

    if (r.line ->> 'track')::boolean then
      update public.products set stock_quantity = stock_quantity - (r.line ->> 'qty')::integer
       where id = (r.line ->> 'product_id')::uuid
      returning stock_quantity into v_after;
      insert into public.inventory_movements (product_id, change, quantity_after, reason, order_id)
      values ((r.line ->> 'product_id')::uuid, -(r.line ->> 'qty')::integer, v_after, 'order_reserved', v_order_id);
    end if;

    if r.line ->> 'item_type' = 'printing' then
      update public.printing_jobs set order_id = v_order_id, customer_id = v_customer_id
       where id = (r.line ->> 'printing_job_id')::uuid;
    end if;
  end loop;

  return jsonb_build_object('order_id', v_order_id, 'order_number', v_order_no,
                            'total_etb', v_subtotal + v_fee - v_discount, 'discount_etb', v_discount, 'replayed', false);
end;
$$;

-- ---------------------------------------------------------------------------
-- Analytics (calendar days in Africa/Addis_Ababa)
--   reports.operational: order counts, statuses, best sellers by quantity, inventory
--   analytics.view:      + all money figures
-- ---------------------------------------------------------------------------
create or replace function public.admin_analytics(p_from date, p_to date, p_bucket text default 'day')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_money  boolean := private.has_permission('analytics.view');
  v_bucket text := case when p_bucket in ('day', 'week', 'month') then p_bucket else 'day' end;
  v_from   timestamptz;
  v_to     timestamptz;
  v_result jsonb;
begin
  if not (v_money or private.has_permission('reports.operational')) then
    perform private.app_error('forbidden', 'analytics.view');
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then
    perform private.app_error('invalid_request');
  end if;
  v_from := p_from::timestamp at time zone 'Africa/Addis_Ababa';
  v_to   := (p_to + 1)::timestamp at time zone 'Africa/Addis_Ababa';

  with
  placed as (select * from public.orders where created_at >= v_from and created_at < v_to),
  paid as (select * from public.orders where payment_status = 'verified'
                    and payment_verified_at >= v_from and payment_verified_at < v_to),
  paid_items as (
    select i.*, p.category_id, coalesce(c.parent_id, c.id) as top_category
      from public.order_items i join paid o on o.id = i.order_id
      left join public.products p on p.id = i.product_id
      left join public.categories c on c.id = p.category_id),
  buckets as (
    select generate_series(date_trunc(v_bucket, p_from::timestamp), p_to::timestamp, ('1 ' || v_bucket)::interval)::date as b)
  select jsonb_build_object(
    'money', v_money,
    'bucket', v_bucket,
    'totals', jsonb_build_object(
      'orders_placed', (select count(*) from placed),
      'orders_paid', (select count(*) from paid),
      'orders_expired', (select count(*) from placed where status = 'expired'),
      'orders_cancelled', (select count(*) from placed where status = 'cancelled'),
      'items_sold', (select coalesce(sum(quantity), 0) from paid_items where item_type = 'product'),
      'revenue', case when v_money then (select coalesce(sum(total_etb), 0) from paid) end,
      'products_revenue', case when v_money then (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'product') end,
      'printing_revenue', case when v_money then (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'printing') end,
      'delivery_fees', case when v_money then (select coalesce(sum(delivery_fee_etb), 0) from paid) end,
      'discounts', case when v_money then (select coalesce(sum(discount_etb), 0) from paid) end,
      'average_order', case when v_money then (select round(avg(total_etb), 2) from paid) end),
    'series', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'bucket', bk.b,
               'orders', (select count(*) from placed o
                           where date_trunc(v_bucket, (o.created_at at time zone 'Africa/Addis_Ababa'))::date = bk.b),
               'paid', (select count(*) from paid o
                         where date_trunc(v_bucket, (o.payment_verified_at at time zone 'Africa/Addis_Ababa'))::date = bk.b),
               'revenue', case when v_money then (select coalesce(sum(o.total_etb), 0) from paid o
                         where date_trunc(v_bucket, (o.payment_verified_at at time zone 'Africa/Addis_Ababa'))::date = bk.b) end)
             order by bk.b), '[]'::jsonb)
        from buckets bk),
    'by_category', (
      select coalesce(jsonb_agg(x order by x.qty desc), '[]'::jsonb) from (
        select coalesce(c.name_en, case when pi.item_type = 'printing' then 'Printing services' else 'Other' end) as name,
               coalesce(c.department::text, case when pi.item_type = 'printing' then 'printing' end) as department,
               sum(pi.quantity) as qty,
               case when v_money then sum(pi.line_total_etb) end as revenue
          from paid_items pi left join public.categories c on c.id = pi.top_category
         group by 1, 2) x),
    'best_sellers', (
      select coalesce(jsonb_agg(x order by x.qty desc, x.name), '[]'::jsonb) from (
        select pi.product_id, max(pi.name_en) as name, max(pi.sku) as sku, sum(pi.quantity) as qty,
               case when v_money then sum(pi.line_total_etb) end as revenue
          from paid_items pi where pi.item_type = 'product'
         group by pi.product_id
         order by sum(pi.quantity) desc
         limit 10) x),
    'statuses', (
      select coalesce(jsonb_object_agg(status, n), '{}'::jsonb)
        from (select status::text, count(*) as n from placed group by 1) s),
    'fulfillment', (
      select coalesce(jsonb_object_agg(fulfillment_method, n), '{}'::jsonb)
        from (select fulfillment_method::text, count(*) as n from placed group by 1) s),
    'promotions', (
      select coalesce(jsonb_agg(x order by x.orders desc), '[]'::jsonb) from (
        select pr.title_en as name, pr.code::text as code, count(*) as orders,
               case when v_money then sum(o.discount_etb) end as discount
          from placed o join public.promotions pr on pr.id = o.promotion_id
         where o.status not in ('expired', 'cancelled')
         group by pr.id) x),
    'inventory', jsonb_build_object(
      'active_products', (select count(*) from public.products where status = 'active'),
      'tracked', (select count(*) from public.products where status = 'active' and track_inventory),
      'out_of_stock', (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity <= 0),
      'low_stock', (select count(*) from public.products where status = 'active' and track_inventory
                      and stock_quantity > 0 and stock_quantity <= low_stock_threshold),
      'units_in_stock', (select coalesce(sum(stock_quantity), 0) from public.products where status = 'active' and track_inventory),
      'stock_value', case when v_money then (select coalesce(sum(stock_quantity * coalesce(sale_price_etb, price_etb)), 0)
                       from public.products where status = 'active' and track_inventory) end)
  ) into v_result;
  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- Customer uploads that were never attached (signed upload URL used, form
-- abandoned). Older than p_min_age; deleted by the daily maintenance cron.
-- ---------------------------------------------------------------------------
create or replace function public.storage_orphans(p_min_age interval default '1 day', p_limit integer default 500)
returns table (bucket text, name text)
language sql
stable
security definer
set search_path = ''
as $$
  select o.bucket_id, o.name
    from storage.objects o
   where o.created_at < now() - greatest(p_min_age, interval '6 hours')
     and (
       (o.bucket_id = 'payment-receipts'
          and not exists (select 1 from public.payment_submissions s where s.receipt_path = o.name))
       or (o.bucket_id = 'printing-files'
          and not exists (select 1 from public.printing_files f where f.storage_path = o.name)))
   order by o.created_at
   limit greatest(1, least(coalesce(p_limit, 500), 1000))
$$;

revoke execute on function public.quote_promotion(text, jsonb, uuid) from public, anon, authenticated;
revoke execute on function public.admin_analytics(date, date, text) from public, anon;
revoke execute on function public.storage_orphans(interval, integer) from public, anon, authenticated;
grant execute on function public.quote_promotion(text, jsonb, uuid) to service_role;
grant execute on function public.admin_analytics(date, date, text) to authenticated;
grant execute on function public.storage_orphans(interval, integer) to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000020_personal_promotions.sql
-- =============================================================================
-- 0020 PERSONAL PROMO CODES
--   * promotions.restricted: only customers listed in promotion_customers can
--     use the code (checked in private.apply_promotion, i.e. inside checkout).
--   * Personal promotions are never public (no homepage, not readable by anon).
--   * Customers see their own codes via my_offers().
--   * Giving / removing a code is recorded in the audit log (customer timeline
--     and Activity log).
-- =============================================================================

alter table public.promotions add column restricted boolean not null default false;
alter table public.promotions add constraint promotions_personal_not_public check (not (restricted and show_on_homepage));

drop policy promotions_public_read on public.promotions;
create policy promotions_public_read on public.promotions for select to anon, authenticated
  using (is_active and show_on_homepage and not restricted
         and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()));

create table public.promotion_customers (
  promotion_id uuid not null references public.promotions(id) on delete cascade,
  user_id      uuid not null references auth.users(id) on delete cascade,
  created_by   uuid references auth.users(id) on delete set null default auth.uid(),
  created_at   timestamptz not null default now(),
  primary key (promotion_id, user_id)
);
create index promotion_customers_user_idx on public.promotion_customers(user_id);

alter table public.promotion_customers enable row level security;
revoke all on public.promotion_customers from anon, authenticated;
grant select, delete on public.promotion_customers to authenticated;
create policy promotion_customers_admin_read on public.promotion_customers for select to authenticated
  using ((select private.has_permission('promotions.manage')));
create policy promotion_customers_admin_delete on public.promotion_customers for delete to authenticated
  using ((select private.has_permission('promotions.manage')));
-- Adding goes through admin_assign_promotion() (resolves emails, validates).

create or replace function private.audit_promotion_customer()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.promotion_customers := coalesce(new, old);
  v_code text;
  v_title text;
begin
  select p.code::text, p.title_en into v_code, v_title from public.promotions p where p.id = r.promotion_id;
  perform private.audit(
    case when tg_op = 'INSERT' then 'promo_assigned' else 'promo_unassigned' end,
    'customer_account', r.user_id::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('code', v_code, 'promotion', v_title, 'promotion_id', r.promotion_id)));
  return r;
end;
$$;
create trigger audit_promotion_customers after insert or delete on public.promotion_customers
  for each row execute function private.audit_promotion_customer();

-- Give a personal promotion to customers by email. Returns what happened per email.
create or replace function public.admin_assign_promotion(p_promotion_id uuid, p_emails text[])
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_promo public.promotions;
  v_email text;
  v_user uuid;
  v_added text[] := '{}';
  v_already text[] := '{}';
  v_missing text[] := '{}';
begin
  perform private.require_permission('promotions.manage');
  select * into v_promo from public.promotions where id = p_promotion_id;
  if not found then perform private.app_error('not_found'); end if;
  if not v_promo.restricted then perform private.app_error('invalid_request', 'promotion is not personal'); end if;
  if p_emails is null or cardinality(p_emails) = 0 or cardinality(p_emails) > 200 then
    perform private.app_error('invalid_request');
  end if;
  foreach v_email in array p_emails loop
    v_email := lower(btrim(v_email));
    continue when v_email = '';
    select u.id into v_user from auth.users u where lower(u.email) = v_email;
    if v_user is null then
      v_missing := v_missing || v_email;
      continue;
    end if;
    insert into public.promotion_customers (promotion_id, user_id) values (p_promotion_id, v_user)
    on conflict do nothing;
    if found then v_added := v_added || v_email; else v_already := v_already || v_email; end if;
  end loop;
  return jsonb_build_object('added', to_jsonb(v_added), 'already', to_jsonb(v_already), 'not_found', to_jsonb(v_missing));
end;
$$;

-- Customers who hold a personal promotion (admin view, with emails and whether they used it).
create or replace function public.admin_promotion_customers(p_promotion_id uuid default null, p_user_id uuid default null)
returns table (promotion_id uuid, user_id uuid, email text, full_name text, code text, title_en text,
               assigned_at timestamptz, used boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('promotions.manage');
  return query
    select pc.promotion_id, pc.user_id, u.email::text, c.full_name, p.code::text, p.title_en, pc.created_at,
           exists (select 1 from public.orders o where o.promotion_id = pc.promotion_id and o.user_id = pc.user_id
                    and o.status not in ('expired', 'cancelled'))
      from public.promotion_customers pc
      join public.promotions p on p.id = pc.promotion_id
      join auth.users u on u.id = pc.user_id
      left join public.customer_accounts c on c.id = pc.user_id
     where (p_promotion_id is null or pc.promotion_id = p_promotion_id)
       and (p_user_id is null or pc.user_id = p_user_id)
     order by pc.created_at desc
     limit 1000;
end;
$$;

-- The signed-in customer's personal codes that can still be used.
create or replace function public.my_offers()
returns table (code text, title_en text, title_am text, description_en text, description_am text,
               discount_type text, discount_value numeric, min_order_etb numeric, ends_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select p.code::text, p.title_en, p.title_am, p.description_en, p.description_am,
         p.discount_type, p.discount_value, p.min_order_etb, p.ends_at
    from public.promotion_customers pc
    join public.promotions p on p.id = pc.promotion_id
   where pc.user_id = (select auth.uid())
     and private.is_active_customer()
     and p.restricted and p.is_active and p.code is not null
     and (p.starts_at is null or p.starts_at <= now()) and (p.ends_at is null or p.ends_at > now())
     and not (p.once_per_customer and exists (
       select 1 from public.orders o where o.promotion_id = p.id and o.user_id = pc.user_id
          and o.status not in ('expired', 'cancelled')))
     and (p.max_redemptions is null or (
       select count(*) from public.orders o where o.promotion_id = p.id
          and o.status not in ('expired', 'cancelled')) < p.max_redemptions)
   order by p.ends_at nulls last, pc.created_at desc
$$;

create or replace function private.apply_promotion(
  p_code text, p_lines jsonb, p_subtotal numeric, p_fee numeric, p_user uuid, p_lock boolean)
returns table (promotion_id uuid, discount_etb numeric, title_en text, title_am text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v        public.promotions;
  v_code   text := lower(btrim(coalesce(p_code, '')));
  v_amount numeric(12,2);
  v_disc   numeric(12,2);
begin
  if v_code !~ '^[a-z0-9_-]{3,30}$' then perform private.app_error('invalid_promo_code'); end if;
  if p_lock then
    select * into v from public.promotions p where lower(p.code::text) = v_code for update;
  else
    select * into v from public.promotions p where lower(p.code::text) = v_code;
  end if;
  if not found or not v.is_active
     or (v.starts_at is not null and v.starts_at > now())
     or (v.ends_at is not null and v.ends_at <= now()) then
    perform private.app_error('invalid_promo_code');
  end if;
  -- Personal codes: only the chosen customer accounts can use them (others: "not valid").
  if v.restricted and (p_user is null or not exists (
       select 1 from public.promotion_customers pc where pc.promotion_id = v.id and pc.user_id = p_user)) then
    perform private.app_error('invalid_promo_code');
  end if;
  if p_subtotal < v.min_order_etb then
    perform private.app_error('promo_min_order', v.min_order_etb::text);
  end if;

  select coalesce(sum((l ->> 'unit')::numeric * (l ->> 'qty')::integer), 0) into v_amount
    from jsonb_array_elements(p_lines) l
    left join public.products pr on pr.id = (l ->> 'product_id')::uuid
    left join public.categories c on c.id = pr.category_id
   where l ->> 'item_type' = 'product'
     and (v.product_id is null or pr.id = v.product_id)
     and (v.category_id is null or pr.category_id = v.category_id or c.parent_id = v.category_id);
  if v_amount <= 0 then perform private.app_error('promo_not_applicable'); end if;

  if v.max_redemptions is not null and (
       select count(*) from public.orders o
        where o.promotion_id = v.id and o.status not in ('expired', 'cancelled')) >= v.max_redemptions then
    perform private.app_error('promo_limit_reached');
  end if;
  if v.once_per_customer and p_user is not null and exists (
       select 1 from public.orders o
        where o.promotion_id = v.id and o.user_id = p_user and o.status not in ('expired', 'cancelled')) then
    perform private.app_error('promo_already_used');
  end if;

  v_disc := case when v.discount_type = 'percent' then round(v_amount * v.discount_value / 100, 2)
                 else least(v.discount_value, v_amount) end;
  v_disc := least(v_disc, p_subtotal + p_fee - 1); -- an order always costs at least 1 ETB
  if v_disc <= 0 then perform private.app_error('promo_not_applicable'); end if;
  return query select v.id, v_disc, v.title_en, v.title_am;
end;
$$;

revoke execute on function public.admin_assign_promotion(uuid, text[]) from public, anon;
revoke execute on function public.admin_promotion_customers(uuid, uuid) from public, anon;
revoke execute on function public.my_offers() from public, anon;
grant execute on function public.admin_assign_promotion(uuid, text[]) to authenticated;
grant execute on function public.admin_promotion_customers(uuid, uuid) to authenticated;
grant execute on function public.my_offers() to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000021_admin_mfa.sql
-- =============================================================================
-- 0021 TWO-STEP LOGIN FOR ADMINS (Supabase Auth MFA, authenticator app / TOTP)
--   Admin permissions now require a session that passed the second step
--   (JWT claim aal = 'aal2'). A stolen password alone (aal1) gives no admin
--   access — not in the app and not through the database API.
--   Customer access is unchanged.
-- =============================================================================

create or replace function private.mfa_verified()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce((select auth.jwt() ->> 'aal'), 'aal1') = 'aal2'
$$;
grant execute on function private.mfa_verified() to authenticated, service_role;

create or replace function private.current_role_key()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select r.key
  from public.profiles p
  join public.admin_roles r on r.id = p.role_id
  where p.id = (select auth.uid()) and p.is_active and private.mfa_verified()
$$;

create or replace function private.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.mfa_verified() and exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid()) and p.is_active
  )
$$;

create or replace function private.has_permission(p_permission text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.mfa_verified() and exists (
    select 1
    from public.profiles p
    join public.role_permissions rp on rp.role_id = p.role_id
    where p.id = (select auth.uid())
      and p.is_active
      and rp.permission_key = p_permission
  )
$$;

create or replace function public.my_admin_context()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when p.id is null then null else jsonb_build_object(
    'user_id', p.id,
    'full_name', p.full_name,
    'role', r.key,
    'permissions', coalesce((
      select jsonb_agg(rp.permission_key order by rp.permission_key)
      from public.role_permissions rp where rp.role_id = p.role_id
    ), '[]'::jsonb)
  ) end
  from (select 1) d
  left join public.profiles p on p.id = (select auth.uid()) and p.is_active and private.mfa_verified()
  left join public.admin_roles r on r.id = p.role_id
$$;

-- Is the signed-in user an active staff member? (No second step needed: used
-- by the sign-in flow to decide whether to ask for the code.)
create or replace function public.my_staff_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'staff', exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.is_active),
    'mfa_verified', private.mfa_verified())
$$;
revoke execute on function public.my_staff_status() from public, anon;
grant execute on function public.my_staff_status() to authenticated;

-- Audit entry when a Super Admin resets a staff member's authenticator
-- (the factor itself is removed through Supabase Auth by the app).
create or replace function public.admin_log_mfa_reset(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('staff.manage');
  if p_user_id = (select auth.uid()) then perform private.app_error('cannot_modify_self'); end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then perform private.app_error('user_not_found'); end if;
  perform private.audit('mfa_reset', 'profiles', p_user_id::text);
end;
$$;
revoke execute on function public.admin_log_mfa_reset(uuid) from public, anon;
grant execute on function public.admin_log_mfa_reset(uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000022_customer_emails.sql
-- =============================================================================
-- 0022 CUSTOMER EMAIL NOTIFICATIONS
--   Same transactional outbox as the staff Telegram alerts (written in the
--   same transaction as the change, retried with backoff), channel 'email'.
--   The recipient is the order's / job's customer account (user id); the
--   address is looked up only when sending, never stored in the outbox.
--   Events: order placed (how to pay), payment confirmed, payment rejected,
--   ready for pickup, out for delivery, completed, cancelled, expired;
--   printing quote ready, printing ready.
-- =============================================================================

alter table public.notifications_outbox drop constraint notifications_outbox_channel_check;
alter table public.notifications_outbox add constraint notifications_outbox_channel_check check (channel in ('telegram', 'email'));
alter table public.notifications_outbox add column recipient_user_id uuid references auth.users(id) on delete cascade;
alter table public.notifications_outbox add constraint notifications_outbox_email_recipient
  check (channel <> 'email' or recipient_user_id is not null);
create index notifications_outbox_channel_due_idx on public.notifications_outbox(channel, next_attempt_at)
  where status in ('pending', 'failed');

create or replace function public.claim_outbox(p_channel text, p_limit integer default 10)
returns setof public.notifications_outbox
language sql
security definer
set search_path = ''
as $$
  update public.notifications_outbox o
     set status = 'processing',
         attempts = o.attempts + 1,
         locked_until = now() + interval '2 minutes'
   where o.id in (
     select id from public.notifications_outbox
      where channel = p_channel
        and ((status in ('pending', 'failed') and next_attempt_at <= now())
          or (status = 'processing' and locked_until < now()))   -- crashed worker
      order by id
      limit greatest(1, least(p_limit, 50))
      for update skip locked
   )
  returning o.*;
$$;

-- The Telegram worker only takes Telegram rows from now on.
create or replace function public.claim_notifications(p_limit integer default 10)
returns setof public.notifications_outbox
language sql
security definer
set search_path = ''
as $$
  select * from public.claim_outbox('telegram', p_limit)
$$;

create or replace function private.enqueue_customer_email(p_event text, p_dedupe text, p_user uuid, p_payload jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, recipient_user_id, max_attempts)
  select 'email', p_event, p_dedupe, p_payload, p_user, 6
   where p_user is not null
  on conflict (dedupe_key) do nothing;
$$;

-- Orders: placed + every customer-relevant status change.
create or replace function private.email_order_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event text;
  v_note text;
begin
  if new.user_id is null then return new; end if;
  if tg_op = 'INSERT' then
    v_event := 'order_placed';
  elsif new.status is distinct from old.status then
    v_event := case new.status
      when 'confirmed' then 'order_confirmed'
      when 'payment_rejected' then 'order_payment_rejected'
      when 'ready_for_pickup' then 'order_ready_for_pickup'
      when 'out_for_delivery' then 'order_out_for_delivery'
      when 'completed' then 'order_completed'
      when 'cancelled' then 'order_cancelled'
      when 'expired' then 'order_expired'
    end;
  end if;
  if v_event is null then return new; end if;
  if v_event = 'order_payment_rejected' then
    select s.review_note into v_note from public.payment_submissions s
     where s.order_id = new.id and s.status = 'rejected' order by s.reviewed_at desc limit 1;
  end if;
  perform private.enqueue_customer_email(
    'customer_' || v_event,
    'email:' || v_event || ':' || new.id || ':' || (select count(*) from public.order_status_history h where h.order_id = new.id),
    new.user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'order_id', new.id, 'order_number', new.order_number, 'total_etb', new.total_etb,
      'fulfillment', new.fulfillment_method, 'locale', new.locale, 'note', v_note,
      'payment_due_at', case when v_event = 'order_placed' then new.payment_due_at end,
      'bank', case when v_event = 'order_placed' then new.bank_snapshot end)));
  return new;
end;
$$;
create trigger email_order_placed after insert on public.orders
  for each row execute function private.email_order_event();
create trigger email_order_status after update of status on public.orders
  for each row execute function private.email_order_event();

-- Printing jobs: quote ready, ready to collect.
create or replace function private.email_printing_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event text;
begin
  if new.user_id is null or new.status is not distinct from old.status then return new; end if;
  v_event := case
    when new.status = 'awaiting_payment' and old.status = 'awaiting_quote' then 'printing_quote_ready'
    when new.status = 'ready' then 'printing_ready'
  end;
  if v_event is null then return new; end if;
  perform private.enqueue_customer_email(
    'customer_' || v_event, 'email:' || v_event || ':' || new.id, new.user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'job_id', new.id, 'job_number', new.job_number, 'total_etb', new.total_etb,
      'fulfillment', new.fulfillment_method)));
  return new;
end;
$$;
create trigger email_printing_status after update of status on public.printing_jobs
  for each row execute function private.email_printing_event();

revoke execute on function public.claim_outbox(text, integer) from public, anon, authenticated;
grant execute on function public.claim_outbox(text, integer) to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000023_customer_push.sql
-- =============================================================================
-- 0023 CUSTOMER PHONE NOTIFICATIONS (Web Push)
--   * push_subscriptions: a customer's devices (browser push endpoints).
--     Customers manage only their own rows; the server sends with VAPID keys.
--   * Every customer email event also queues a 'push' outbox row (same
--     transaction, retried independently, sent to all of the customer's devices).
-- =============================================================================

create table public.push_subscriptions (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade default auth.uid(),
  -- Only real browser push services (the server POSTs to this URL).
  endpoint     text not null unique check (char_length(endpoint) <= 1000 and endpoint ~
    '^https://(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|web\.push\.apple\.com|[a-z0-9-]+\.notify\.windows\.com|[a-z0-9-]+\.push\.apple\.com)/'),
  p256dh       text not null check (p256dh ~ '^[A-Za-z0-9_-]{40,200}$'),
  auth         text not null check (auth ~ '^[A-Za-z0-9_-]{10,100}$'),
  locale       text not null default 'en' check (locale in ('en', 'am')),
  user_agent   text check (char_length(user_agent) <= 300),
  created_at   timestamptz not null default now(),
  last_used_at timestamptz
);
create index push_subscriptions_user_idx on public.push_subscriptions(user_id);

alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from anon, authenticated;
grant select, delete on public.push_subscriptions to authenticated;
grant insert (endpoint, p256dh, auth, locale, user_agent) on public.push_subscriptions to authenticated;
create policy push_subscriptions_own_read on public.push_subscriptions for select to authenticated
  using (user_id = (select auth.uid()));
create policy push_subscriptions_own_insert on public.push_subscriptions for insert to authenticated
  with check (user_id = (select auth.uid()) and (select private.is_active_customer()));
create policy push_subscriptions_own_delete on public.push_subscriptions for delete to authenticated
  using (user_id = (select auth.uid()));

-- At most 10 devices per customer: the oldest is dropped.
create or replace function private.push_subscriptions_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.push_subscriptions
   where user_id = new.user_id and id in (
     select id from public.push_subscriptions where user_id = new.user_id order by created_at desc offset 10);
  return null;
end;
$$;
create trigger push_subscriptions_limit after insert on public.push_subscriptions
  for each row execute function private.push_subscriptions_limit();

-- Outbox: new channel
alter table public.notifications_outbox drop constraint notifications_outbox_channel_check;
alter table public.notifications_outbox add constraint notifications_outbox_channel_check check (channel in ('telegram', 'email', 'push'));
alter table public.notifications_outbox drop constraint notifications_outbox_email_recipient;
alter table public.notifications_outbox add constraint notifications_outbox_email_recipient
  check (channel = 'telegram' or recipient_user_id is not null);

-- Each customer event: email + phone notification.
create or replace function private.enqueue_customer_email(p_event text, p_dedupe text, p_user uuid, p_payload jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, recipient_user_id, max_attempts)
  select c.channel, p_event, c.prefix || p_dedupe, p_payload, p_user, c.attempts
    from (values ('email', '', 6), ('push', 'push:', 4)) c(channel, prefix, attempts)
   where p_user is not null
     and (c.channel = 'email' or exists (select 1 from public.push_subscriptions s where s.user_id = p_user))
  on conflict (dedupe_key) do nothing;
$$;

-- Worker: the customer's devices (service_role only).
create or replace function public.push_targets(p_user_id uuid)
returns table (id uuid, endpoint text, p256dh text, auth text, locale text)
language sql
stable
security definer
set search_path = ''
as $$
  select s.id, s.endpoint, s.p256dh, s.auth, s.locale from public.push_subscriptions s where s.user_id = p_user_id
$$;
revoke execute on function public.push_targets(uuid) from public, anon, authenticated;
grant execute on function public.push_targets(uuid) to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000024_export_audit.sql
-- =============================================================================
-- 0024 EXPORT AUDIT
--   Order exports contain customer names, phones and addresses: every export
--   is recorded in the audit log (who, when, which period, how many rows).
-- =============================================================================

create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('orders.view_all');
  if p_kind not in ('orders') then perform private.app_error('invalid_request'); end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;
revoke execute on function public.admin_log_export(text, jsonb) from public, anon;
grant execute on function public.admin_log_export(text, jsonb) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000025_staff_not_customers.sql
-- =============================================================================
-- 0025 STAFF ACCOUNTS ARE NOT CUSTOMER ACCOUNTS
--   Admin/staff logins cannot place orders or printing jobs (the app also
--   refuses them on the customer sign-in). Staff shop with a separate email.
-- =============================================================================

create or replace function private.assert_confirmed_user(p_user_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_user_id is null or not exists (
    select 1 from auth.users where id = p_user_id and email_confirmed_at is not null
  ) then
    perform private.app_error('login_required');
  end if;
  if not private.is_active_user(p_user_id) then
    perform private.app_error('account_deactivated');
  end if;
  if exists (select 1 from public.profiles where id = p_user_id) then
    perform private.app_error('staff_account');
  end if;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000026_wallet.sql
-- =============================================================================
-- 0026 WALLET (shop credit)
--   * Customers top up by bank transfer + receipt; a Manager / Super Admin
--     (wallet.manage) verifies the money arrived, then the balance is credited.
--   * Maximum balance 10,000 ETB (top-ups and manual credits are refused above it).
--   * The balance can pay an order only if it covers the WHOLE total; such an
--     order is confirmed immediately (same transaction as the order).
--   * No withdrawals: cancelling a balance-paid order refunds the balance.
--   * Every change is a row in the append-only wallet_ledger; the current
--     balance lives on customer_accounts and can never go below 0.
-- =============================================================================

insert into public.admin_permissions (key, description) values
  ('wallet.manage', 'Verify wallet top-ups and see customer balances'),
  ('wallet.adjust', 'Correct a customer balance manually')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select r.id, p.key from public.admin_roles r join public.admin_permissions p on p.key in ('wallet.manage', 'wallet.adjust')
 where r.key = 'super_admin'
on conflict do nothing;
insert into public.role_permissions (role_id, permission_key)
select id, 'wallet.manage' from public.admin_roles where key = 'manager'
on conflict do nothing;

create or replace function private.wallet_max()
returns numeric language sql immutable set search_path = '' as $$ select 10000::numeric $$;

alter table public.customer_accounts
  add column wallet_balance_etb numeric(12,2) not null default 0 check (wallet_balance_etb >= 0);

alter table public.orders
  add column payment_method text not null default 'bank_transfer' check (payment_method in ('bank_transfer', 'wallet'));

-- ---------------------------------------------------------------------------
-- Top-up requests
-- ---------------------------------------------------------------------------
create sequence public.wallet_topup_number_seq start 1001;
create table public.wallet_topups (
  id                    uuid primary key default gen_random_uuid(),
  topup_number          text not null unique default ('TU-' || nextval('public.wallet_topup_number_seq')),
  user_id               uuid not null references auth.users(id) on delete restrict,
  amount_etb            numeric(12,2) not null check (amount_etb >= 10 and amount_etb <= 10000),
  transaction_reference text check (transaction_reference ~ '^[A-Za-z0-9/_ -]{3,60}$'),
  receipt_path          text not null unique check (receipt_path ~ '^topups/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|pdf)$'),
  receipt_mime          text not null check (receipt_mime in ('image/jpeg', 'image/png', 'application/pdf')),
  receipt_size_bytes    integer not null check (receipt_size_bytes between 1 and 10485760),
  receipt_sha256        text not null check (receipt_sha256 ~ '^[0-9a-f]{64}$'),
  bank_snapshot         jsonb,
  status                text not null default 'pending' check (status in ('pending', 'verified', 'rejected')),
  review_note           text check (char_length(review_note) <= 1000),
  reviewed_by           uuid references auth.users(id) on delete set null,
  reviewed_at           timestamptz,
  created_at            timestamptz not null default now(),
  check ((status = 'pending') = (reviewed_at is null)),
  check (status <> 'rejected' or review_note is not null)
);
create index wallet_topups_user_idx on public.wallet_topups(user_id, created_at desc);
create index wallet_topups_pending_idx on public.wallet_topups(created_at) where status = 'pending';

-- ---------------------------------------------------------------------------
-- Ledger (append-only)
-- ---------------------------------------------------------------------------
create table public.wallet_ledger (
  id                bigint generated always as identity primary key,
  user_id           uuid not null references auth.users(id) on delete restrict,
  amount_etb        numeric(12,2) not null check (amount_etb <> 0),
  balance_after_etb numeric(12,2) not null check (balance_after_etb >= 0),
  kind              text not null check (kind in ('topup', 'order_payment', 'refund', 'adjustment')),
  topup_id          uuid references public.wallet_topups(id) on delete restrict,
  order_id          uuid references public.orders(id) on delete restrict,
  note              text check (char_length(note) <= 500),
  created_by        uuid references auth.users(id) on delete set null default auth.uid(),
  created_at        timestamptz not null default now()
);
create index wallet_ledger_user_idx on public.wallet_ledger(user_id, id desc);

create or replace function private.prevent_ledger_mutation()
returns trigger language plpgsql set search_path = '' as $$
begin
  raise exception 'wallet_ledger is append-only';
end;
$$;
create trigger wallet_ledger_immutable before update or delete on public.wallet_ledger
  for each row execute function private.prevent_ledger_mutation();

-- RLS: customers read their own; wallet.manage reads all; nobody writes directly.
alter table public.wallet_topups enable row level security;
alter table public.wallet_ledger enable row level security;
revoke all on public.wallet_topups, public.wallet_ledger from anon, authenticated;
grant select on public.wallet_topups, public.wallet_ledger to authenticated;
create policy wallet_topups_own_read on public.wallet_topups for select to authenticated
  using (user_id = (select auth.uid()));
create policy wallet_topups_admin_read on public.wallet_topups for select to authenticated
  using ((select private.has_permission('wallet.manage')));
create policy wallet_ledger_own_read on public.wallet_ledger for select to authenticated
  using (user_id = (select auth.uid()));
create policy wallet_ledger_admin_read on public.wallet_ledger for select to authenticated
  using ((select private.has_permission('wallet.manage')));

-- Wallet managers can open top-up receipts (signed URLs).
create policy "topup receipts: wallet managers read" on storage.objects for select to authenticated
  using (bucket_id = 'payment-receipts' and name like 'topups/%' and (select private.has_permission('wallet.manage')));

-- ---------------------------------------------------------------------------
-- Core: move money (locks the account row; balance can never go below 0)
-- ---------------------------------------------------------------------------
create or replace function private.wallet_post(
  p_user uuid, p_amount numeric, p_kind text, p_topup uuid default null, p_order uuid default null, p_note text default null)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_balance numeric(12,2);
begin
  insert into public.customer_accounts (id) values (p_user) on conflict do nothing;
  select wallet_balance_etb into v_balance from public.customer_accounts where id = p_user for update;
  v_balance := v_balance + p_amount;
  if v_balance < 0 then perform private.app_error('wallet_insufficient'); end if;
  update public.customer_accounts set wallet_balance_etb = v_balance where id = p_user;
  insert into public.wallet_ledger (user_id, amount_etb, balance_after_etb, kind, topup_id, order_id, note)
  values (p_user, p_amount, v_balance, p_kind, p_topup, p_order, left(p_note, 500));
  return v_balance;
end;
$$;

-- ---------------------------------------------------------------------------
-- Customer: request a top-up (server only, after the receipt was verified by content)
-- p_input = { amount_etb, transaction_reference?, receipt: { path, mime, size, sha256 } }
-- ---------------------------------------------------------------------------
create or replace function public.submit_wallet_topup(p_user_id uuid, p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_amount   numeric;
  v_ref      text := nullif(btrim(coalesce(p_input ->> 'transaction_reference', '')), '');
  v_balance  numeric;
  v_pending  numeric;
  v_count    integer;
  v_bank     public.bank_accounts;
  v_topup    public.wallet_topups;
  v_seen     boolean;
begin
  perform private.assert_confirmed_user(p_user_id);
  if coalesce(p_input ->> 'amount_etb', '') !~ '^[0-9]{1,5}(\.[0-9]{1,2})?$' then perform private.app_error('invalid_amount'); end if;
  v_amount := (p_input ->> 'amount_etb')::numeric;
  if v_amount < 10 or v_amount > private.wallet_max() then perform private.app_error('invalid_amount'); end if;
  if v_ref is not null and v_ref !~ '^[A-Za-z0-9/_ -]{3,60}$' then perform private.app_error('invalid_reference'); end if;
  if coalesce(p_input #>> '{receipt,path}', '') !~ ('^topups/' || p_user_id || '/[0-9a-f-]{36}\.(jpg|png|pdf)$') then
    perform private.app_error('upload_failed');
  end if;

  -- Serialize this customer's top-ups so the limit check cannot be raced.
  perform 1 from public.customer_accounts where id = p_user_id for update;
  select coalesce(wallet_balance_etb, 0) into v_balance from public.customer_accounts where id = p_user_id;
  select coalesce(sum(amount_etb), 0), count(*) into v_pending, v_count
    from public.wallet_topups where user_id = p_user_id and status = 'pending';
  if v_count >= 3 then perform private.app_error('topup_pending_limit'); end if;
  if coalesce(v_balance, 0) + v_pending + v_amount > private.wallet_max() then
    perform private.app_error('wallet_limit', greatest(0, private.wallet_max() - coalesce(v_balance, 0) - v_pending)::text);
  end if;

  select * into v_bank from public.bank_accounts where is_active order by sort_order, created_at limit 1;
  v_seen := (v_ref is not null and (
               exists (select 1 from public.payment_submissions s where lower(s.transaction_reference) = lower(v_ref))
            or exists (select 1 from public.wallet_topups t where lower(t.transaction_reference) = lower(v_ref))))
         or exists (select 1 from public.payment_submissions s where s.receipt_sha256 = p_input #>> '{receipt,sha256}')
         or exists (select 1 from public.wallet_topups t where t.receipt_sha256 = p_input #>> '{receipt,sha256}');

  insert into public.wallet_topups (user_id, amount_etb, transaction_reference, receipt_path, receipt_mime, receipt_size_bytes, receipt_sha256, bank_snapshot)
  values (p_user_id, v_amount, v_ref, p_input #>> '{receipt,path}', p_input #>> '{receipt,mime}', (p_input #>> '{receipt,size}')::integer,
          p_input #>> '{receipt,sha256}',
          case when v_bank.id is not null then jsonb_build_object('bank_name', v_bank.bank_name, 'account_number', v_bank.account_number) end)
  returning * into v_topup;

  perform private.enqueue_notification('wallet_topup', 'wallet_topup:' || v_topup.id,
    jsonb_build_object('topup_number', v_topup.topup_number, 'amount_etb', v_amount,
      'customer', (select coalesce(c.full_name, u.email::text) from auth.users u left join public.customer_accounts c on c.id = u.id where u.id = p_user_id),
      'transaction_reference', v_ref, 'reference_seen_before', v_seen),
    'payment-receipts', v_topup.receipt_path);
  return jsonb_build_object('topup_id', v_topup.id, 'topup_number', v_topup.topup_number, 'reference_seen_before', v_seen);
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin: verify / reject a top-up
-- ---------------------------------------------------------------------------
create or replace function public.admin_review_topup(p_topup_id uuid, p_decision text, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v       public.wallet_topups;
  v_note  text := nullif(btrim(coalesce(p_note, '')), '');
  v_bal   numeric;
begin
  perform private.require_permission('wallet.manage');
  select * into v from public.wallet_topups where id = p_topup_id;
  if not found then perform private.app_error('not_found'); end if;
  perform 1 from public.customer_accounts where id = v.user_id for update;
  select * into v from public.wallet_topups where id = p_topup_id for update;
  if v.status <> 'pending' then perform private.app_error('already_reviewed'); end if;

  if p_decision = 'verified' then
    if (select coalesce(wallet_balance_etb, 0) from public.customer_accounts where id = v.user_id) + v.amount_etb > private.wallet_max() then
      perform private.app_error('wallet_limit');
    end if;
    v_bal := private.wallet_post(v.user_id, v.amount_etb, 'topup', v.id, null, coalesce(v_note, 'Top-up ' || v.topup_number));
    update public.wallet_topups set status = 'verified', reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = v_note where id = v.id;
  elsif p_decision = 'rejected' then
    if v_note is null then perform private.app_error('note_required'); end if;
    update public.wallet_topups set status = 'rejected', reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = v_note where id = v.id;
    select wallet_balance_etb into v_bal from public.customer_accounts where id = v.user_id;
  else
    perform private.app_error('invalid_decision');
  end if;

  perform private.audit('topup_' || p_decision, 'customer_account', v.user_id::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('topup_number', v.topup_number, 'amount_etb', v.amount_etb, 'reason', v_note)));
  perform private.enqueue_customer_email('customer_topup_' || p_decision, 'topup:' || v.id || ':' || p_decision, v.user_id,
    jsonb_strip_nulls(jsonb_build_object('topup_number', v.topup_number, 'amount_etb', v.amount_etb, 'balance_etb', v_bal, 'note', v_note)));
  return jsonb_build_object('balance_etb', v_bal);
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin: manual correction (Super Admin), with a reason
-- ---------------------------------------------------------------------------
create or replace function public.admin_adjust_wallet(p_user_id uuid, p_amount numeric, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_bal    numeric;
begin
  perform private.require_permission('wallet.adjust');
  perform private.assert_manageable_customer(p_user_id);
  if p_amount is null or p_amount = 0 or abs(p_amount) > private.wallet_max() or p_amount <> round(p_amount, 2) then
    perform private.app_error('invalid_amount');
  end if;
  if v_reason is null or char_length(v_reason) > 500 then perform private.app_error('invalid_reason'); end if;
  perform 1 from public.customer_accounts where id = p_user_id for update;
  if p_amount > 0 and (select coalesce(wallet_balance_etb, 0) from public.customer_accounts where id = p_user_id) + p_amount > private.wallet_max() then
    perform private.app_error('wallet_limit');
  end if;
  v_bal := private.wallet_post(p_user_id, p_amount, 'adjustment', null, null, v_reason);
  perform private.audit('wallet_adjusted', 'customer_account', p_user_id::text, null, null,
    jsonb_build_object('amount_etb', p_amount, 'balance_etb', v_bal, 'reason', v_reason));
  return jsonb_build_object('balance_etb', v_bal);
end;
$$;

-- ---------------------------------------------------------------------------
-- Pay an order with the balance (whole total only), inside checkout
-- ---------------------------------------------------------------------------
create or replace function private.pay_order_from_wallet(p_order_id uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders;
begin
  select * into v from public.orders where id = p_order_id for update;
  if not found or v.user_id is distinct from p_user then perform private.app_error('order_not_found'); end if;
  if v.payment_status = 'verified' and v.payment_method = 'wallet' then return; end if; -- idempotent replay
  if v.status <> 'awaiting_payment' or v.payment_status <> 'unpaid' then perform private.app_error('payment_not_allowed'); end if;
  perform private.wallet_post(p_user, -v.total_etb, 'order_payment', null, v.id, 'Order ' || v.order_number);
  perform private.set_status_note('Paid with account balance');
  update public.orders
     set status = 'confirmed', payment_status = 'verified', payment_method = 'wallet', payment_verified_at = now()
   where id = v.id;
  update public.printing_jobs set status = 'printing'
   where order_id = v.id and status in ('awaiting_payment', 'payment_verification');
  -- The "please pay by bank transfer" messages queued a moment ago no longer apply.
  delete from public.notifications_outbox
   where status = 'pending' and event_type = 'customer_order_placed' and payload ->> 'order_id' = v.id::text;
  -- Staff: a new paid order to prepare.
  perform private.enqueue_notification('wallet_order_paid', 'wallet_order:' || v.id,
    jsonb_build_object('order_id', v.id, 'order_number', v.order_number, 'total_etb', v.total_etb,
      'customer_name', v.customer_name, 'customer_phone', v.customer_phone, 'fulfillment_method', v.fulfillment_method,
      'city', v.city, 'address_line', v.address_line,
      'items', (select jsonb_agg(jsonb_build_object('name', i.name_en, 'quantity', i.quantity)) from public.order_items i where i.order_id = v.id)));
end;
$$;

create or replace function public.create_order_for_user(p_user_id uuid, p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_existing public.orders;
  v_result jsonb;
begin
  perform private.assert_confirmed_user(p_user_id);
  -- An idempotent replay must come from the same account.
  select * into v_existing from public.orders where idempotency_key = (p_input ->> 'idempotency_key')::uuid;
  if found and v_existing.user_id is distinct from p_user_id then
    perform private.app_error('idempotency_conflict');
  end if;
  -- Retry of a checkout that was already paid with the balance: same order, fresh access tokens, no second charge.
  if found and v_existing.payment_method = 'wallet' then
    update public.orders
       set access_token_hash = p_input ->> 'access_token_hash', tracking_code_hash = p_input ->> 'tracking_code_hash'
     where id = v_existing.id;
    return jsonb_build_object('order_id', v_existing.id, 'order_number', v_existing.order_number,
                              'total_etb', v_existing.total_etb, 'replayed', true, 'paid_with_wallet', true);
  end if;
  perform set_config('app.ordering_user_id', p_user_id::text, true);
  v_result := public.create_order(p_input);
  -- Clear immediately so nothing later in the same transaction inherits this user.
  perform set_config('app.ordering_user_id', '', true);
  delete from public.customer_carts where user_id = p_user_id;
  -- Pay with the account balance: all or nothing (an insufficient balance cancels the whole checkout).
  if p_input ->> 'payment_method' = 'wallet' then
    perform private.pay_order_from_wallet((v_result ->> 'order_id')::uuid, p_user_id);
    v_result := v_result || jsonb_build_object('paid_with_wallet', true);
  end if;
  return v_result;
end;
$$;

-- Cancelling a balance-paid order refunds the balance (no cash withdrawals).
create or replace function private.refund_wallet_order()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'cancelled' and old.status <> 'cancelled' and new.payment_method = 'wallet' and old.payment_status = 'verified' then
    perform private.wallet_post(new.user_id, new.total_etb, 'refund', null, new.id, 'Refund: order ' || new.order_number || ' cancelled');
    new.payment_status := 'refunded';
  end if;
  return new;
end;
$$;
create trigger orders_wallet_refund before update of status on public.orders
  for each row execute function private.refund_wallet_order();

-- Top-up receipts are attached uploads too: never treat them as orphans.
create or replace function public.storage_orphans(p_min_age interval default '1 day', p_limit integer default 500)
returns table (bucket text, name text)
language sql
stable
security definer
set search_path = ''
as $$
  select o.bucket_id, o.name
    from storage.objects o
   where o.created_at < now() - greatest(p_min_age, interval '6 hours')
     and (
       (o.bucket_id = 'payment-receipts'
          and not exists (select 1 from public.payment_submissions s where s.receipt_path = o.name)
          and not exists (select 1 from public.wallet_topups t where t.receipt_path = o.name))
       or (o.bucket_id = 'printing-files'
          and not exists (select 1 from public.printing_files f where f.storage_path = o.name)))
   order by o.created_at
   limit greatest(1, least(coalesce(p_limit, 500), 1000))
$$;

-- Admin overview of balances (customers with money, newest activity first).
create or replace function public.admin_wallet_balances(p_search text default null, p_limit integer default 100)
returns table (user_id uuid, email text, full_name text, balance_etb numeric, last_activity timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('wallet.manage');
  return query
    select c.id, u.email::text, c.full_name, c.wallet_balance_etb,
           (select max(l.created_at) from public.wallet_ledger l where l.user_id = c.id)
      from public.customer_accounts c join auth.users u on u.id = c.id
     where (c.wallet_balance_etb > 0 or exists (select 1 from public.wallet_ledger l where l.user_id = c.id))
       and (v_q is null or u.email ilike '%' || v_q || '%' or c.full_name ilike '%' || v_q || '%')
     order by 5 desc nulls last
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

revoke execute on function public.submit_wallet_topup(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.submit_wallet_topup(uuid, jsonb) to service_role;
revoke execute on function public.admin_review_topup(uuid, text, text) from public, anon;
revoke execute on function public.admin_adjust_wallet(uuid, numeric, text) from public, anon;
revoke execute on function public.admin_wallet_balances(text, integer) from public, anon;
grant execute on function public.admin_review_topup(uuid, text, text) to authenticated;
grant execute on function public.admin_adjust_wallet(uuid, numeric, text) to authenticated;
grant execute on function public.admin_wallet_balances(text, integer) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000027_security_monitoring.sql
-- =============================================================================
-- 0027 SECURITY & HEALTH MONITORING
--   * security_events: failed / blocked sign-ins (with the EMAIL that was
--     used), two-step failures, successful admin sign-ins, rate-limit hits.
--     Network addresses are stored only as a truncated hash.
--   * blocked_emails: an email on this list cannot sign up, sign in or order
--     (checked by the app AND by the database, incl. direct API sign-ups).
--   * Super Admin views: suspicious emails, suspicious customers, admin
--     sign-ins, site health (queues, overdue work, scheduled jobs).
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('security.manage', 'Block and unblock emails')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select id, 'security.manage' from public.admin_roles where key = 'super_admin'
on conflict do nothing;

create table public.security_events (
  id         bigint generated always as identity primary key,
  kind       text not null check (kind in (
               'admin_login_failed', 'admin_login_not_staff', 'admin_mfa_failed', 'admin_login_success',
               'customer_login_failed', 'staff_customer_login', 'login_blocked', 'signup_blocked', 'rate_limited')),
  email      text check (char_length(email) <= 254),
  user_id    uuid references auth.users(id) on delete set null,
  ip_hash    text check (ip_hash ~ '^[0-9a-f]{8,64}$'),
  user_agent text check (char_length(user_agent) <= 300),
  metadata   jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index security_events_email_idx on public.security_events(email, created_at desc);
create index security_events_kind_idx on public.security_events(kind, created_at desc);

create table public.blocked_emails (
  email      text primary key check (email = lower(email) and char_length(email) between 3 and 254),
  reason     text not null check (char_length(reason) between 2 and 500),
  blocked_by uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now()
);

create table public.cron_runs (
  name        text primary key check (name ~ '^[a-z-]{3,40}$'),
  last_run_at timestamptz not null,
  last_ok     boolean not null,
  detail      jsonb not null default '{}'::jsonb
);

-- All three: server / definer functions only.
alter table public.security_events enable row level security;
alter table public.blocked_emails enable row level security;
alter table public.cron_runs enable row level security;
revoke all on public.security_events, public.blocked_emails, public.cron_runs from anon, authenticated;

create or replace function private.email_is_blocked(p_email text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.blocked_emails b where b.email = lower(btrim(coalesce(p_email, ''))))
$$;

-- Backstop for sign-ups made directly against the Supabase API.
create or replace function private.refuse_blocked_signup()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if private.email_is_blocked(new.email) then
    raise exception using errcode = 'P0001', message = 'email_blocked';
  end if;
  return new;
end;
$$;
create trigger refuse_blocked_signup before insert on auth.users
  for each row execute function private.refuse_blocked_signup();

-- Ordering / top-ups: refuse blocked emails (on top of deactivation).
create or replace function private.assert_confirmed_user(p_user_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_email text;
begin
  select email into v_email from auth.users where id = p_user_id and email_confirmed_at is not null;
  if p_user_id is null or v_email is null then
    perform private.app_error('login_required');
  end if;
  if not private.is_active_user(p_user_id) then
    perform private.app_error('account_deactivated');
  end if;
  if exists (select 1 from public.profiles where id = p_user_id) then
    perform private.app_error('staff_account');
  end if;
  if private.email_is_blocked(v_email) then
    perform private.app_error('email_blocked');
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Server API (service_role)
-- ---------------------------------------------------------------------------
create or replace function public.record_security_event(
  p_kind text, p_email text default null, p_user_id uuid default null, p_ip_hash text default null,
  p_user_agent text default null, p_metadata jsonb default '{}'::jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.security_events (kind, email, user_id, ip_hash, user_agent, metadata)
  values (p_kind, nullif(lower(btrim(left(coalesce(p_email, ''), 254))), ''), p_user_id, p_ip_hash, left(p_user_agent, 300),
          coalesce(p_metadata, '{}'::jsonb));
$$;

create or replace function public.is_email_blocked(p_email text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$ select private.email_is_blocked(p_email) $$;

create or replace function public.record_cron_run(p_name text, p_ok boolean, p_detail jsonb default '{}'::jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.cron_runs (name, last_run_at, last_ok, detail) values (p_name, now(), p_ok, coalesce(p_detail, '{}'::jsonb))
  on conflict (name) do update set last_run_at = excluded.last_run_at, last_ok = excluded.last_ok, detail = excluded.detail;
$$;

-- Old events are removed after 180 days (called by the daily maintenance job).
create or replace function public.purge_security_events()
returns integer
language sql
security definer
set search_path = ''
as $$
  with d as (delete from public.security_events where created_at < now() - interval '180 days' returning 1)
  select count(*)::integer from d
$$;

-- ---------------------------------------------------------------------------
-- Super Admin: block / unblock
-- ---------------------------------------------------------------------------
create or replace function public.admin_block_email(p_email text, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email  text := lower(btrim(coalesce(p_email, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_user   uuid;
begin
  perform private.require_permission('security.manage');
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' or char_length(v_email) > 254 then perform private.app_error('invalid_request'); end if;
  if v_reason is null or char_length(v_reason) > 500 then perform private.app_error('invalid_reason'); end if;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is not null and exists (select 1 from public.profiles where id = v_user) then
    perform private.app_error('cannot_manage_staff');
  end if;
  insert into public.blocked_emails (email, reason) values (v_email, v_reason)
  on conflict (email) do update set reason = excluded.reason, blocked_by = auth.uid(), created_at = now();
  -- An existing customer account is deactivated (the app also bans its sign-in).
  if v_user is not null then
    insert into public.customer_accounts (id) values (v_user) on conflict do nothing;
    update public.customer_accounts
       set deactivated_at = coalesce(deactivated_at, now()), deactivated_by = coalesce(deactivated_by, auth.uid()),
           deactivation_reason = coalesce(deactivation_reason, left('Blocked email: ' || v_reason, 500))
     where id = v_user;
  end if;
  perform private.audit('email_blocked', 'security', v_email, null, null, jsonb_build_object('reason', v_reason, 'user_id', v_user));
  return jsonb_build_object('email', v_email, 'user_id', v_user);
end;
$$;

create or replace function public.admin_unblock_email(p_email text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_user  uuid;
begin
  perform private.require_permission('security.manage');
  delete from public.blocked_emails where email = v_email;
  if not found then perform private.app_error('not_found'); end if;
  select id into v_user from auth.users where lower(email) = v_email;
  -- Reactivate only if the account was deactivated BY the block.
  if v_user is not null then
    update public.customer_accounts set deactivated_at = null, deactivated_by = null, deactivation_reason = null
     where id = v_user and deactivation_reason like 'Blocked email:%';
    if not found then v_user := null; end if;
  end if;
  perform private.audit('email_unblocked', 'security', v_email);
  return jsonb_build_object('email', v_email, 'reactivated_user_id', v_user);
end;
$$;

-- ---------------------------------------------------------------------------
-- Super Admin views (audit.view)
-- ---------------------------------------------------------------------------
create or replace function public.admin_suspicious_emails(p_days integer default 7)
returns table (email text, failed_admin bigint, failed_mfa bigint, failed_customer bigint, blocked_attempts bigint, rate_limited bigint,
               networks bigint, last_seen timestamptz, has_account boolean, is_staff boolean, blocked boolean, score bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
  with e as (
    select s.email,
           count(*) filter (where s.kind in ('admin_login_failed', 'admin_login_not_staff')) as fa,
           count(*) filter (where s.kind = 'admin_mfa_failed') as fm,
           count(*) filter (where s.kind = 'customer_login_failed') as fc,
           count(*) filter (where s.kind in ('login_blocked', 'signup_blocked')) as fb,
           count(*) filter (where s.kind = 'rate_limited') as rl,
           count(distinct s.ip_hash) as nets,
           max(s.created_at) as last
      from public.security_events s
     where s.email is not null and s.kind <> 'admin_login_success'
       and s.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 180)))
     group by s.email)
  select e.email, e.fa, e.fm, e.fc, e.fb, e.rl, e.nets, e.last,
         exists (select 1 from auth.users u where lower(u.email) = e.email),
         exists (select 1 from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = e.email),
         private.email_is_blocked(e.email),
         -- admin attempts weigh more than customer typos
         e.fa * 3 + e.fm * 4 + e.fc + e.fb * 2 + e.rl * 2 + greatest(e.nets - 1, 0) * 2
    from e
   order by 12 desc, e.last desc
   limit 300;
end;
$$;

create or replace function public.admin_suspicious_customers(p_days integer default 30)
returns table (user_id uuid, email text, full_name text, expired_orders bigint, cancelled_unpaid bigint, rejected_payments bigint,
               rejected_topups bigint, reused_receipts bigint, failed_logins bigint, idle_basket_hours integer,
               deactivated boolean, blocked boolean, reasons text[])
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_since timestamptz := now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 365)));
begin
  perform private.require_permission('audit.view');
  return query
  with c as (
    select u.id, u.email::text as email, ca.full_name, ca.deactivated_at is not null as deact,
      (select count(*) from public.orders o where o.user_id = u.id and o.status = 'expired' and o.created_at > v_since) as exp,
      (select count(*) from public.orders o where o.user_id = u.id and o.status = 'cancelled' and o.payment_verified_at is null and o.created_at > v_since) as canc,
      (select count(*) from public.payment_submissions s join public.orders o on o.id = s.order_id
        where o.user_id = u.id and s.status = 'rejected' and s.submitted_at > v_since) as rejp,
      (select count(*) from public.wallet_topups t where t.user_id = u.id and t.status = 'rejected' and t.created_at > v_since) as rejt,
      (select count(*) from public.payment_submissions s join public.orders o on o.id = s.order_id
        where o.user_id = u.id and s.submitted_at > v_since and (
          exists (select 1 from public.payment_submissions s2 join public.orders o2 on o2.id = s2.order_id
                   where o2.user_id <> u.id and (s2.receipt_sha256 = s.receipt_sha256
                     or (s.transaction_reference is not null and lower(s2.transaction_reference) = lower(s.transaction_reference))))
          or exists (select 1 from public.wallet_topups t where t.user_id <> u.id and t.receipt_sha256 = s.receipt_sha256))) as reused,
      (select count(*) from public.security_events e where lower(e.email) = lower(u.email::text) and e.kind = 'customer_login_failed' and e.created_at > v_since) as fails,
      (select floor(extract(epoch from now() - k.updated_at) / 3600)::integer from public.customer_carts k where k.user_id = u.id and k.item_count > 0) as idle
    from auth.users u
    left join public.customer_accounts ca on ca.id = u.id
    where not exists (select 1 from public.profiles p where p.id = u.id))
  select c.id, c.email, c.full_name, c.exp, c.canc, c.rejp, c.rejt, c.reused, c.fails, c.idle, c.deact, private.email_is_blocked(c.email),
         array_remove(array[
           case when c.exp + c.canc >= 3 then 'Many orders placed but never paid' end,
           case when c.rejp + c.rejt >= 2 then 'Several receipts rejected' end,
           case when c.reused > 0 then 'Receipt or bank reference also used by another customer' end,
           case when c.fails >= 5 then 'Many failed sign-ins' end,
           case when c.idle >= 72 and c.exp + c.canc >= 1 then 'Leaves baskets and unpaid orders repeatedly' end], null)
    from c
   where c.exp + c.canc >= 3 or c.rejp + c.rejt >= 2 or c.reused > 0 or c.fails >= 5 or (c.idle >= 72 and c.exp + c.canc >= 1)
   order by (c.reused * 5 + (c.rejp + c.rejt) * 3 + c.exp + c.canc + c.fails) desc
   limit 200;
end;
$$;

create or replace function public.admin_security_events(p_kind text default null, p_email text default null, p_limit integer default 100)
returns table (id bigint, kind text, email text, user_name text, ip_hash text, user_agent text, metadata jsonb, created_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
    select s.id, s.kind, s.email, private.actor_name(s.user_id), left(s.ip_hash, 8), s.user_agent, s.metadata, s.created_at
      from public.security_events s
     where (p_kind is null or s.kind = p_kind) and (p_email is null or s.email = lower(btrim(p_email)))
     order by s.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

create or replace function public.admin_blocked_emails()
returns table (email text, reason text, blocked_by text, created_at timestamptz, has_account boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
    select b.email, b.reason, private.actor_name(b.blocked_by), b.created_at,
           exists (select 1 from auth.users u where lower(u.email) = b.email)
      from public.blocked_emails b order by b.created_at desc;
end;
$$;

-- Site health: queues, overdue work, scheduled jobs, alerts in the last 24 h.
create or replace function public.admin_system_health()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return jsonb_build_object(
    'outbox', (select coalesce(jsonb_object_agg(channel, x), '{}'::jsonb) from (
        select channel, jsonb_build_object(
          'pending', count(*) filter (where status in ('pending', 'processing')),
          'failed', count(*) filter (where status = 'failed'),
          'dead_7d', count(*) filter (where status = 'dead' and created_at > now() - interval '7 days'),
          'oldest_pending', min(created_at) filter (where status in ('pending', 'failed'))) as x
          from public.notifications_outbox group by channel) t),
    'payments_pending', (select count(*) from public.payment_submissions where status = 'pending'),
    'payments_oldest', (select min(submitted_at) from public.payment_submissions where status = 'pending'),
    'topups_pending', (select count(*) from public.wallet_topups where status = 'pending'),
    'topups_oldest', (select min(created_at) from public.wallet_topups where status = 'pending'),
    'overdue_unexpired', (select count(*) from public.orders where status in ('awaiting_payment', 'payment_rejected') and payment_due_at < now() - interval '2 hours'),
    'paid_waiting_24h', (select count(*) from public.orders where status = 'confirmed' and payment_verified_at < now() - interval '24 hours'),
    'out_of_stock', (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity <= 0),
    'cron', (select coalesce(jsonb_object_agg(name, jsonb_build_object('last_run_at', last_run_at, 'ok', last_ok, 'detail', detail)), '{}'::jsonb) from public.cron_runs),
    'events_24h', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (
        select kind, count(*) as n from public.security_events where created_at > now() - interval '24 hours' group by kind) k),
    'blocked_emails', (select count(*) from public.blocked_emails)
  );
end;
$$;

